import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;import vn.rtr.aeris.mission.*;
public final class BootstrapProbe{
 static int tests;static void need(boolean b,String s){if(!b)throw new AssertionError(s);tests++;}interface Check{void run()throws Exception;}static void reject(Check r)throws Exception{boolean refused=false;try{r.run();}catch(Exception e){refused=true;}need(refused,"accepted invalid");}
 public static void main(String[]a)throws Exception{String raw=new String(Files.readAllBytes(Paths.get(a[0])),StandardCharsets.UTF_8);MissionBootstrap b=MissionBootstrap.parse(raw);need(b.baseRevision==1&&b.viewEpoch==17,"descriptor");b.validateIdentity(b.processEpoch,17,1,b.sourceSHA256);tests++;
 for(String field:new String[]{"version","viewEpoch","baseRevision"})for(Object v:new Object[]{1.0,1.5,true,"1"}){JSONObject o=new JSONObject(raw);o.put(field,v);reject(()->MissionBootstrap.parse(o.toString()));}
 for(String field:new String[]{"version","targetSystem"})for(Object v:new Object[]{1.0,42.0,1.5,42.5,true,"42"}){JSONObject o=new JSONObject(raw);o.getJSONObject("provider").put(field,v);reject(()->MissionBootstrap.parse(o.toString()));}
 JSONObject o=new JSONObject(raw);o.getJSONObject("provider").put("rootOwnedContainer","true");reject(()->MissionBootstrap.parse(o.toString()));reject(()->b.validateIdentity("d".repeat(32),17,1,b.sourceSHA256));reject(()->b.validateIdentity(b.processEpoch,18,1,b.sourceSHA256));reject(()->b.validateIdentity(b.processEpoch,17,2,b.sourceSHA256));
 MissionBootstrap.IntentQueue q=new MissionBootstrap.IntentQueue();q.enqueue("BOOTSTRAP",raw,100);need(q.consume(101,false)==null,"foreground");MissionBootstrap.Dispatch d=q.consume(102,true);need(d.receivedNs==100,"original receipt");q.enqueue("BOOTSTRAP",raw,1000);need(q.consume(1001,true).receivedNs==100,"replay retimestamped");JSONObject conflict=new JSONObject(raw);conflict.put("sourceSHA256","e".repeat(64));reject(()->q.enqueue("BOOTSTRAP",conflict.toString(),1002));reject(()->q.enqueue("BOOTSTRAP",raw,10000000101L));
 MissionBootstrap.IntentQueue expired=new MissionBootstrap.IntentQueue();expired.enqueue("BOOTSTRAP",raw,0);reject(()->expired.consume(2000000001L,true));MissionBootstrap.IntentQueue backwards=new MissionBootstrap.IntentQueue();backwards.enqueue("BOOTSTRAP",raw,100);reject(()->backwards.consume(99,true));
 MissionBootstrap.IntentQueue capacity=new MissionBootstrap.IntentQueue();capacity.enqueue("BOOTSTRAP",raw,100);JSONObject status=new JSONObject().put("version",1).put("requestNonce","f".repeat(32));reject(()->capacity.enqueue("STATUS",status.toString(),101));
 MissionLifecycle life=new MissionLifecycle();life.stage(b);need(life.duplicate(b),"duplicate");reject(()->life.duplicate(MissionBootstrap.parse(conflict.toString())));System.out.println(new JSONObject().put("status","PASS_BUILDER_HOST_JVM_ONLY").put("assertions",tests).put("AndroidParserOrDevice",false));}
}
